package com.icbc.changzhou.ipam;

import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import com.google.gson.JsonObject;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

/** No-framework stage-three regression.  Runs against a real V006-to-V007 SQLite upgrade path. */
public final class StageThreeSmokeTest {
  public static void main(String[] args) throws Exception {
    Path work=Files.createTempDirectory("ipam-stage3-");Path db=work.resolve("v006-upgrade.db");
    try(Connection c=open(db)){
      apply(c,"V001__stage1_foundation.sql");apply(c,"V002__remove_backup_role_and_tech_scope.sql");
      c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password) VALUES('admin','x','管理员','ADMIN',1,0)");
      apply(c,"V003__initial_admin_protection.sql");apply(c,"V004__bulk_import_and_application_workflow.sql");apply(c,"V005__outlet_range_and_default_pool.sql");apply(c,"V006__organization_soft_delete_and_network_defaults.sql");
      c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password) VALUES('tech','x','科技管理员','TECH_ADMIN',1,0)");
      c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password) VALUES('disabled','x','停用管理员','ADMIN',0,0)");
      c.createStatement().execute("INSERT INTO branch(code,name) VALUES('B1','测试支行')");c.createStatement().execute("INSERT INTO outlet(branch_id,code,name) VALUES(1,'O1','测试网点')");
      c.createStatement().execute("INSERT INTO ip_range(branch_id,outlet_id,cidr,subnet_mask,gateway,dns_primary) VALUES(1,1,'10.10.0.0/24','255.255.255.0','10.10.0.1','8.8.8.8')");
      c.createStatement().execute("INSERT INTO ip_address_pool(ip_range_id,ip_address) VALUES(1,'10.10.0.8')");
      c.createStatement().execute("INSERT INTO ip_application(applicant_user_id,applicant_name,unified_auth_id,branch_id,outlet_id,asset_type,asset_code,device_type,status) VALUES(2,'科技管理员','900000001',1,1,'TECH','ASSET-1','PC','APPROVED')");
      c.createStatement().execute("INSERT INTO ip_assignment(application_id,ip_pool_id,resource_code,assigned_by) VALUES(1,1,'ASSET-1',1)");
      apply(c,"V007__immediate_release_notification_statistics_export.sql");apply(c,"V008__outlet_directory_information.sql");apply(c,"V009__remove_redundant_managed_outlet_no.sql");apply(c,"V010__six_network_planning_and_asset_mapping.sql");apply(c,"V011__outlet_plan_batch_import.sql");apply(c,"V019__password_policy_and_switch_port.sql");c.createStatement().execute("CREATE TABLE asset_definition (id INTEGER PRIMARY KEY,asset_type TEXT NOT NULL,name TEXT NOT NULL,requires_user INTEGER NOT NULL DEFAULT 0,requires_resource_code INTEGER NOT NULL DEFAULT 0,recommended_range_type TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 1,deleted_at TEXT,created_by INTEGER)");apply(c,"V020__manual_assignment_and_gateway.sql");apply(c,"V021__mac_address.sql");apply(c,"V022__resource_maintenance.sql");
      try(ResultSet r=c.createStatement().executeQuery("SELECT status FROM ip_assignment WHERE id=1")){if(!r.next()||!"ASSIGNED".equals(r.getString(1)))throw new AssertionError("V006 assignment must become ASSIGNED");}
    }
    PhaseThreeService phase3=new PhaseThreeService(db);Map<String,Object> released=phase3.release(1L,2L,"设备下线","stage3-request-1");if(!"RELEASED".equals(released.get("status")))throw new AssertionError("release did not return RELEASED");
    try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM ip_release_event",1);assertCount(c,"SELECT count(*) FROM user_notification WHERE release_event_id IS NOT NULL AND user_id=1",1);assertCount(c,"SELECT count(*) FROM user_notification WHERE release_event_id IS NOT NULL AND user_id=3",0);assertCount(c,"SELECT count(*) FROM audit_log WHERE action='RELEASE_IP'",1);}
    boolean repeat=false;try{phase3.release(1L,2L,"again","stage3-request-2");}catch(PhaseTwoService.Problem e){repeat="IP_ALREADY_RELEASED".equals(e.code);}if(!repeat)throw new AssertionError("repeat release must be rejected");
    boolean forbidden=false;try{phase3.release(1L,1L,"bad","stage3-request-3");}catch(PhaseTwoService.Problem e){forbidden="RELEASE_FORBIDDEN".equals(e.code);}if(!forbidden)throw new AssertionError("non-owner must not release");
    PhaseTwoService phase2=new PhaseTwoService(db);try(Connection c=open(db)){c.createStatement().execute("INSERT INTO ip_application(applicant_user_id,applicant_name,unified_auth_id,branch_id,outlet_id,asset_type,asset_code,device_type,status) VALUES(2,'科技管理员','900000002',1,1,'TECH','ASSET-1','PC','PENDING')");}if(phase2.availableIps(2L,"10.10.0.8",1).size()!=1)throw new AssertionError("released IP must become available");phase2.approve(2L,1L,1L);if(((Number)phase2.ranges().get(0).get("assignmentCount")).longValue()!=1L)throw new AssertionError("range must count only active assignment");
    Map<String,Object> pool=phase2.poolItems(null,null,"900000002",1);Map<String,Object> poolItem=((List<Map<String,Object>>)pool.get("items")).get(0);if(((Number)pool.get("total")).longValue()!=1L||!"科技管理员".equals(poolItem.get("applicantName"))||poolItem.get("branchName")==null||poolItem.get("outletName")==null||poolItem.get("cidr")==null)throw new AssertionError("global pool assignee search/details missing");
    boolean unavailableProbe=false;try{phase3.reachability(1L);}catch(PhaseTwoService.Problem e){unavailableProbe="IP_NOT_AVAILABLE".equals(e.code);}if(!unavailableProbe)throw new AssertionError("assigned IP must not be probed as available");
    Map<String,Object> overview=phase3.overview(null,null);if(((Number)overview.get("assignedCount")).longValue()!=1L||((Number)overview.get("releasedTotal")).longValue()!=1L)throw new AssertionError("overview totals do not match data");
    byte[] csv=phase3.export("RELEASE","CSV",new LinkedHashSet<String>(),new LinkedHashMap<String,String>(),1L);if(csv.length<3||csv[0]!=(byte)0xef||csv[1]!=(byte)0xbb||csv[2]!=(byte)0xbf)throw new AssertionError("CSV BOM missing");
    Set<String> onlyIp=new LinkedHashSet<>();onlyIp.add("ipAddress");String selectedCsv=new String(phase3.export("RELEASE","CSV",onlyIp,new LinkedHashMap<String,String>(),1L),StandardCharsets.UTF_8);if(!selectedCsv.startsWith("\uFEFF\"ipAddress\"")||selectedCsv.contains("resourceCode"))throw new AssertionError("selected export fields not honored");
    byte[] xlsx=phase3.export("RELEASE","XLSX",new LinkedHashSet<String>(),new LinkedHashMap<String,String>(),1L);if(xlsx.length<4||xlsx[0]!='P'||xlsx[1]!='K')throw new AssertionError("XLSX output invalid");
    boolean forceReason=false;try{phase3.forceRelease(2L,1L,"","stage3-force-missing");}catch(PhaseTwoService.Problem e){forceReason="FORCE_RELEASE_REASON_REQUIRED".equals(e.code);}if(!forceReason)throw new AssertionError("force release reason must be required");
    Map<String,Object> forced=phase3.forceRelease(2L,1L,"管理员回收","stage3-force-release");if(!"RELEASED".equals(forced.get("status")))throw new AssertionError("admin force release failed");
    try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM audit_log WHERE action='ADMIN_FORCE_RELEASE_IP'",1);}if(((Number)phase2.ranges().get(0).get("assignmentCount")).longValue()!=0L)throw new AssertionError("released assignment must not remain in range count");
    OutletDirectoryService directory=new OutletDirectoryService(db);Map<String,Object> imported=directory.importXlsx("outlet-directory.xlsx",directoryXlsx(),1L);if(((Number)imported.get("insertedRows")).intValue()!=1||directory.list(null,"展示网点").size()!=1)throw new AssertionError("outlet directory XLSX import failed");JsonObject directoryEdit=new JsonObject();directoryEdit.addProperty("outletNo","OUTLET-1");directoryEdit.addProperty("orgCode","ORG-2");directoryEdit.addProperty("outletName","展示网点更新");directoryEdit.addProperty("outletAddress","常州市测试路 2 号");directoryEdit.addProperty("phone","0519-87654321");directoryEdit.addProperty("branchId",1);directory.update(1L,directoryEdit,1L);if(directory.list(null,"更新").size()!=1)throw new AssertionError("outlet directory edit failed");Map<String,Object> duplicate=directory.importXlsx("outlet-directory.xlsx",directoryXlsx(),1L);if(((Number)duplicate.get("errorRows")).intValue()!=1)throw new AssertionError("duplicate outlet directory import must be atomic");if(directory.template().length<4)throw new AssertionError("outlet directory template missing");
    verifyRuntimeUpgradeAndPasswordChange(work.resolve("runtime-v006.db"));
    System.out.println("PASS|STAGE3_V009_RELEASE_NOTIFY_REUSE_STATS_EXPORT_OUTLET_DIRECTORY_POOL_OPERATIONS|"+work);
  }
  private static void verifyRuntimeUpgradeAndPasswordChange(Path db)throws Exception{
    try(Connection c=open(db)){apply(c,"V001__stage1_foundation.sql");apply(c,"V002__remove_backup_role_and_tech_scope.sql");c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password) VALUES('runtimeadmin','x','运行管理员','ADMIN',1,1)");c.createStatement().execute("CREATE TABLE schema_history (version TEXT PRIMARY KEY, description TEXT NOT NULL, checksum TEXT NOT NULL, installed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))) ");try(PreparedStatement p=c.prepareStatement("INSERT INTO schema_history(version,description,checksum) VALUES(?,?,?)")){p.setString(1,"001");p.setString(2,"stage1 foundation");p.setString(3,checksum("V001__stage1_foundation.sql"));p.executeUpdate();p.setString(1,"002");p.setString(2,"remove backup role and tech scope");p.setString(3,checksum("V002__remove_backup_role_and_tech_scope.sql"));p.executeUpdate();}}
    Class<?> type=Class.forName("com.icbc.changzhou.ipam.IpamApplication$Database");java.lang.reflect.Constructor<?> ctor=type.getDeclaredConstructor(Path.class);ctor.setAccessible(true);Object runtime=ctor.newInstance(db);java.lang.reflect.Method migrate=type.getDeclaredMethod("migrate");migrate.setAccessible(true);migrate.invoke(runtime);java.lang.reflect.Method change=type.getDeclaredMethod("changePassword",long.class,String.class);change.setAccessible(true);change.invoke(runtime,1L,"new-password");
    try(Connection c=open(db);Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT (SELECT count(*) FROM schema_history WHERE version='011'),must_change_password FROM sys_user WHERE id=1")){if(!r.next()||r.getInt(1)!=1||r.getInt(2)!=0)throw new AssertionError("runtime migration or password change failed");}
    System.out.println("PASS|RUNTIME_V011_MIGRATION_AND_PASSWORD_CHANGE");
  }
  private static byte[] directoryXlsx()throws Exception{try(XSSFWorkbook wb=new XSSFWorkbook();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){Sheet s=wb.createSheet("template");String[] h={"outlet_no","org_code","outlet_name","outlet_address","phone","branch_code"};String[] v={"OUTLET-1","ORG-1","展示网点","常州市测试路 1 号","0519-12345678","B1"};Row header=s.createRow(0),row=s.createRow(1);for(int i=0;i<h.length;i++){header.createCell(i).setCellValue(h[i]);row.createCell(i).setCellValue(v[i]);}wb.write(out);return out.toByteArray();}}
  private static Connection open(Path db)throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");}return c;}
  private static String checksum(String name)throws Exception{byte[] bytes=StageThreeSmokeTest.class.getResourceAsStream("/db/migration/"+name).readAllBytes();byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder out=new StringBuilder();for(byte b:hash)out.append(String.format("%02x",b));return out.toString();}
  private static void apply(Connection c,String name)throws Exception{String resource="/db/migration/"+name;String sql=new String(StageThreeSmokeTest.class.getResourceAsStream(resource).readAllBytes(),StandardCharsets.UTF_8);boolean rebuild=name.startsWith("V020");try(Statement s=c.createStatement()){if(rebuild)s.execute("PRAGMA foreign_keys=OFF");for(String part:sql.split(";\\s*(?:\\r?\\n|$)"))if(!part.trim().isEmpty())s.execute(part);if(rebuild)s.execute("PRAGMA foreign_keys=ON");}}
  private static void assertCount(Connection c,String sql,long expected)throws Exception{try(ResultSet r=c.createStatement().executeQuery(sql)){r.next();if(r.getLong(1)!=expected)throw new AssertionError(sql+" expected "+expected+" actual "+r.getLong(1));}}
}
